import{_ as o,o as d,c as t,a2 as c}from"./chunks/framework.D0_YsCyK.js";const h=JSON.parse('{"title":"审查域 E 报告：前端功能可用性","description":"","frontmatter":{},"headers":[],"relativePath":"audit/E-frontend.md","filePath":"audit/E-frontend.md","lastUpdated":1792447441000}'),i={name:"audit/E-frontend.md"};function l(a,e,r,n,s,u){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="审查域-e-报告-前端功能可用性" tabindex="-1">审查域 E 报告：前端功能可用性 <a class="header-anchor" href="#审查域-e-报告-前端功能可用性" aria-label="Permalink to &quot;审查域 E 报告：前端功能可用性&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>审查范围：7 批移植功能的前端挂载完整性、前后端字段契约一致性、订阅编辑页状态管理</li><li>发现问题数：<strong>P0 2 个</strong> / P1 0 个 / P2 1 个 / P3 0 个</li><li>实际执行的检查：静态代码审查（字段对照、挂载点 grep、API 路径对照）；<strong>无浏览器环境，页面实际渲染未验证</strong></li></ul><hr><h2 id="p0-阻断" tabindex="-1">P0 阻断 <a class="header-anchor" href="#p0-阻断" aria-label="Permalink to &quot;P0 阻断&quot;">​</a></h2><h3 id="e-001-订阅规则-脚本-链式多选字段在后端-http-层被完全丢弃" tabindex="-1">E-001 订阅规则/脚本/链式多选字段在后端 HTTP 层被完全丢弃 <a class="header-anchor" href="#e-001-订阅规则-脚本-链式多选字段在后端-http-层被完全丢弃" aria-label="Permalink to &quot;E-001 订阅规则/脚本/链式多选字段在后端 HTTP 层被完全丢弃&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/subscription.go:30-52</code></li><li>现象：前端订阅编辑页「规则与脚本」区可正常填写（开关、规则分组多选、脚本编辑器均已挂载），保存后后端静默丢弃；重新打开编辑页时已填内容丢失；预览接口同样无效果。</li><li>复现步骤： <ol><li>前端 <code>SubPipeline</code> 类型已含 5 个新字段（<code>vite-frontend/src/api/index.ts:661-682</code>：<code>rules</code>、<code>ruleGroups</code>、<code>chainLandingNames</code>、<code>chainRelayNames</code>、<code>script</code>），<code>EMPTY_PIPELINE</code> 已初始化（<code>vite-frontend/src/pages/subscription.tsx:61-80</code>），<code>toPayload</code> 经 <code>...rest</code> 透传全部字段（<code>subscription.tsx:326-337</code>）。</li><li>后端 <code>subPipeline</code> 结构体（<code>subscription.go:30-43</code>）只有 13 个旧字段，缺失上述 5 个 → <code>json.Unmarshal</code> 时直接丢弃。</li><li><code>options()</code>（<code>:45-51</code>）未映射 5 个字段 → <code>kernel.SubOptions</code> 永远收不到。</li><li><code>parsePipeline</code>（<code>:82-92</code>）反序列化用同一结构体 → 数据库读回时同样丢失，编辑页回显为空。</li><li><code>subscriptionPreview</code>（<code>:702</code>）走同一 <code>subscriptionRequest</code> → 预览也不生效。</li></ol></li><li>期望：保存的规则/脚本/链式多选能持久化并作用于订阅渲染。</li><li>实际：Web 层该功能完全不可用（仅单元测试能通过）。</li><li>影响范围：订阅规则引擎、订阅脚本、链式代理多选三个移植功能在 Web 端全部失效。</li><li>修复方向：给 <code>subPipeline</code> 补 5 个字段 + json tag；在 <code>options()</code> 中映射到 <code>kernel.SubOptions</code>；在 <code>normalize()</code> 中补校验（<code>RuleGroups</code> 建议调 <code>kernel.NormalizeRuleGroups</code> 过滤未知 key，<code>Script</code> 限长）。</li></ul><h3 id="e-002-订阅列表接口未下发规则分组清单-前端分组复选框永不渲染" tabindex="-1">E-002 订阅列表接口未下发规则分组清单，前端分组复选框永不渲染 <a class="header-anchor" href="#e-002-订阅列表接口未下发规则分组清单-前端分组复选框永不渲染" aria-label="Permalink to &quot;E-002 订阅列表接口未下发规则分组清单，前端分组复选框永不渲染&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/subscription.go:447-450</code></li><li>现象：即使 E-001 修复，前端「规则分组」复选框依然不会出现。</li><li>证据： <ul><li>前端从列表接口读取分组清单：<code>setRuleGroups(subRes.data.ruleGroups ?? [])</code>（<code>vite-frontend/src/pages/subscription.tsx:902</code>）。</li><li>后端 <code>subscriptionList</code> 响应只含 <code>items</code> 和 <code>regions</code>（<code>subscription.go:447-450</code>），无 <code>ruleGroups</code> 键 → 前端恒得 <code>[]</code>。</li><li>分组复选框渲染条件为 <code>{o.rules &amp;&amp; ruleGroups.length &gt; 0 &amp;&amp; (...)}</code>（<code>subscription.tsx:759</code>）→ 永假。</li><li>后端已有现成的数据源 <code>kernel.RuleGroups()</code>（<code>go-backend/internal/kernel/sub_rules.go:84</code>，返回 <code>[]RuleGroup{Key, Name}</code> 且 json tag 与前端 <code>SubRuleGroup</code>（<code>api/index.ts:684-687</code>）一致），只是未在接口中暴露。</li></ul></li><li>期望：打开规则开关后可勾选 10 个规则分组。</li><li>实际：只能开总开关，无法选择分组（<code>o.ruleGroups</code> 恒空）。</li><li>影响范围：订阅规则引擎的分组粒度分流不可用。</li><li>修复方向：在 <code>subscriptionList</code> 响应中增加 <code>&quot;ruleGroups&quot;: kernel.RuleGroups()</code>。</li></ul><hr><h2 id="p2-一般" tabindex="-1">P2 一般 <a class="header-anchor" href="#p2-一般" aria-label="Permalink to &quot;P2 一般&quot;">​</a></h2><h3 id="e-003-subpipeline-normalize-未处理新字段" tabindex="-1">E-003 <code>subPipeline.normalize()</code> 未处理新字段 <a class="header-anchor" href="#e-003-subpipeline-normalize-未处理新字段" aria-label="Permalink to &quot;E-003 `subPipeline.normalize()` 未处理新字段&quot;">​</a></h3><ul><li>文件：<code>go-backend/internal/http/handler/subscription.go:54-78</code></li><li>现象：<code>normalize()</code> 只 trim 旧字段（<code>Rename</code>/<code>Include</code>/<code>Exclude</code>/<code>ChainLanding</code>/<code>ChainRelay</code>），<code>Script</code> 未做去空白/限长，<code>RuleGroups</code> 未做 key 白名单过滤。</li><li>影响：脏数据可入库；未知 group key 会在渲染层被静默忽略（<code>enabledRuleGroups</code> 按 key 匹配），用户勾选了不存在的分组也无提示。</li><li>修复方向：<code>Script</code> 限长（如 20000 字符，与 <code>sub_script.go</code> 上限一致）；<code>RuleGroups = kernel.NormalizeRuleGroups(p.RuleGroups)</code>。</li></ul><hr><h2 id="已验证通过的项-有证据" tabindex="-1">已验证通过的项（有证据） <a class="header-anchor" href="#已验证通过的项-有证据" aria-label="Permalink to &quot;已验证通过的项（有证据）&quot;">​</a></h2><h3 id="e1-挂载完整性" tabindex="-1">E1 挂载完整性 <a class="header-anchor" href="#e1-挂载完整性" aria-label="Permalink to &quot;E1 挂载完整性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>功能</th><th>挂载点</th><th>证据</th></tr></thead><tbody><tr><td>延迟显示（列表）</td><td><code>node.tsx:1997</code> <code>renderLatency(node, &quot;list&quot;)</code></td><td>TableCell 渲染，无条件</td></tr><tr><td>延迟显示（卡片）</td><td><code>node.tsx:2266-2268</code></td><td><code>node.latency &amp;&amp;</code> 条件已移除，始终渲染（此前 P1 遗留 bug 已修）</td></tr><tr><td>延迟检测/路由/测试点入口</td><td><code>components/latency-cell.tsx:229,237,355-372</code></td><td>「检测」按钮、「回程路由」、「测试点」下拉项均存在</td></tr><tr><td>调优入口</td><td><code>node.tsx:2056-2061</code>（列表）、<code>2566-2568</code>（卡片）</td><td>nftables 模式隐藏逻辑存在</td></tr><tr><td>调优弹窗</td><td><code>node.tsx:3562</code> <code>&lt;NodeTuneModal&gt;</code></td><td>已挂载</td></tr><tr><td>路由弹窗</td><td><code>node.tsx:3563-3567</code> <code>&lt;RouteModal nodeId nodeName&gt;</code></td><td>props 与 <code>route-modal.tsx:105-106</code> 一致</td></tr><tr><td>测试点弹窗</td><td><code>node.tsx:3568-3572</code></td><td><code>onSaved</code> 后 <code>loadNodes({silent:true})</code> 刷新</td></tr><tr><td>测试点配置</td><td><code>config.tsx:42,1709</code> <code>&lt;LatencySettings&gt;</code></td><td>已挂载</td></tr><tr><td>订阅规则/脚本 UI</td><td><code>subscription.tsx:739-799</code></td><td>「规则与脚本」Section、开关、分组复选框、脚本编辑器均存在</td></tr></tbody></table><h3 id="e2-前后端契约-除-e-001-e-002-外" tabindex="-1">E2 前后端契约（除 E-001/E-002 外） <a class="header-anchor" href="#e2-前后端契约-除-e-001-e-002-外" aria-label="Permalink to &quot;E2 前后端契约（除 E-001/E-002 外）&quot;">​</a></h3><ul><li>5 个延迟/调优/路由 API 路径前后端一致：<code>/node/latency/probe</code>、<code>/node/latency/targets</code>、<code>/node/tune</code>、<code>/node/route</code>、<code>/node/route/probe</code>（前端 <code>api/index.ts:867-925</code>，后端 <code>handler.go:231-237</code>）。</li><li><code>RouteModal</code> 的 <code>nodeId: number | null</code> 与调用方 <code>routeNode?.id ?? null</code> 一致。</li><li>订阅保存后刷新列表：<code>save()</code> 内 <code>await load()</code>（<code>subscription.tsx:938</code>）。</li><li><code>draftFrom</code> 用 <code>{ ...EMPTY_PIPELINE, ...s.options }</code> 合并（<code>subscription.tsx:315</code>），后端一旦返回新字段即能正确回显，无需前端改动。</li><li>链式多选 UI 未移植属已知缺口（类型已就位），本次不计为缺陷。</li></ul><hr><h2 id="未能验证的项" tabindex="-1">未能验证的项 <a class="header-anchor" href="#未能验证的项" aria-label="Permalink to &quot;未能验证的项&quot;">​</a></h2><ul><li>延迟单元格的实际渲染效果、颜色分档、探测按钮交互：未验证，需人工在浏览器确认（无浏览器环境）。</li><li>调优弹窗、路由弹窗、测试点弹窗的实际打开与交互：未验证，需人工在浏览器确认。</li><li>订阅规则开关/分组/脚本的端到端保存→预览：未验证（被 E-001/E-002 阻断，修复后需重验）。</li><li>旧浏览器/移动端布局：未验证。</li></ul>',22)])])}const b=o(i,[["render",l]]);export{h as __pageData,b as default};
